reply.content:
{
  "sop_id": "notify-vendor",
  "milestones": [
    {
      "id": "M1",
      "target": "Vendor Sharma Logistics Pvt Ltd and invoice INV-1043 are identified.",
      "sop_step": "NV-1",
      "predicates": [
        {
          "read": "find_vendors",
          "args": {
            "q": "Sharma Logistics Pvt Ltd"
          },
          "where": {
            "name": "Sharma Logistics Pvt Ltd"
          }
        },
        {
          "read": "list_invoices",
          "args": {
            "vendor": {
              "ref": "M1"
            }
          },
          "where": {
            "invoice_no": "INV-1043"
          }
        }
      ]
    },
    {
      "id": "M2",
      "target": "Email is sent to the vendor's contact email address.",
      "sop_step": "NV-4",
      "after": [
        "M1"
      ],
      "predicates": [
        {
          "read": "list_mail",
          "args": {
            "folder": "outbox"
          },
          "where": {
            "to_addr": "accounts@sharmalogistics.example"
          },
          "contains": {
            "subject": [
              "INV-1043",
              "review"
            ]
          }
        }
      ],
      "judge": [
        "The email subject and body clearly state that invoice INV-1043 is under review."
      ]
    }
  ]
}

